// ========================================
// 6天分批抓取配置
// ========================================
const TOTAL_PAGES = 111;     // 总共111页
const DAYS = 6;              // 分6天抓取
const PAGES_PER_DAY = 19;    // 每天19页

// 极致了API配置
const CONFIG = {
  accountName: '饼干哥哥AGI',
  apiKey: 'JZLdc9670be1403c05c',
  baseUrl: 'https://www.dajiala.com/fbmain/monitor/v3/post_history',
  pagesPerDay: PAGES_PER_DAY,
  delayMs: 3000               // 3秒间隔（更安全）
};

// 飞书应用配置（已填写）
const FEISHU_CONFIG = {
  appId: 'cli_a907365bcefbdbd2',
  appSecret: 'UOnIdOt4xWAgLrzVJUmrQbAOu8Icetjv'
};

// 计算今天应该从第几页开始
const today = new Date();
const startDay = 0;  // 第0天开始，每次执行会自动计算

// 从文件读取上次抓取状态（如果有）
let lastPage = 0;

return [{
  json: {
    config: CONFIG,
    feishu: FEISHU_CONFIG,
    currentPage: lastPage + 1,
    startPage: lastPage + 1,
    endPage: Math.min(lastPage + PAGES_PER_DAY, TOTAL_PAGES),
    totalPages: TOTAL_PAGES,
    allArticles: [],
    totalCost: 0,
    dayInfo: {
      currentDay: Math.floor(lastPage / PAGES_PER_DAY) + 1,
      totalDays: DAYS,
      pagesToday: PAGES_PER_DAY
    }
  }
}];

// 合并飞书Token和文章数据
const tokenData = $input.all()[0].json;
const articleData = $input.all()[1].json;

return [{
  json: {
    ...articleData,
    feishuToken: tokenData.tenant_access_token
  }
}];

const response = $input.first().json;
const endPage = $input.first().json.endPage;

if (response.code !== 0) {
  if (response.code === 110) {
    console.log('✅ 已到达最后一页');
    return [{json: {...$input.first().json, hasMore: false, isComplete: true}}];
  }
  if (response.code === 115) {
    console.log('✅ 后续页面文章已删除');
    return [{json: {...$input.first().json, hasMore: false}}];
  }
  throw new Error(`API错误 [${response.code}]: ${response.msg}`);
}

const articles = response.data || [];
const currentPage = $input.first().json.currentPage;
const allArticles = $input.first().json.allArticles || [];

// 去重
const existingIds = new Set(allArticles.map(a => a.appmsgid));
const newArticles = articles.filter(a => !existingIds.has(a.appmsgid));
allArticles.push(...newArticles);

// 检查是否完成今天的任务
const hasMore = currentPage < endPage;
const todayProgress = currentPage - $input.first().json.startPage + 1;
const todayTotal = $input.first().json.endPage - $input.first().json.startPage + 1;

console.log(`📄 第 ${currentPage} 页: ${newArticles.length} 篇新文章`);
console.log(`📊 今日进度: ${todayProgress}/${todayTotal} 页 (${Math.round(todayProgress/todayTotal*100)}%)`);
console.log(`📈 总计: ${allArticles.length} 篇文章`);

return [{
  json: {
    ...$input.first().json,
    articles: newArticles,
    allArticles,
    hasMore,
    nextPage: currentPage + 1,
    remainMoney: response.remain_money,
    totalCost: ($input.first().json.totalCost || 0) + (response.cost_money || 0)
  }
}];

// ========================================
// 生成飞书文档内容
// ========================================
const data = $input.first().json;
const articles = data.allArticles;

// 按日期分组
const grouped = {};
articles.forEach(article => {
  const date = article.post_time_str.split(' ')[0];
  if (!grouped[date]) grouped[date] = [];
  grouped[date].push(article);
});

// 生成Markdown
let content = `# 📰 饼干哥哥AGI - 文章汇总\n\n`;
content += `## 📊 统计信息\n\n`;
content += `- **抓取时间**: ${new Date().toLocaleString()}\n`;
content += `- **今日抓取**: ${data.endPage - data.startPage + 1} 页\n`;
content += `- **文章总数**: ${articles.length} 篇\n`;
content += `- **总费用**: ${data.totalCost.toFixed(2)} 元\n`;
content += `- **账户余额**: ${data.remainMoney} 元\n`;
content += `- **抓取进度**: 第 ${data.dayInfo.currentDay}/${data.dayInfo.totalDays} 天\n\n`;
content += `---\n\n`;

// 按日期倒序排列
const sortedDates = Object.keys(grouped).sort((a, b) => new Date(b) - new Date(a));

sortedDates.forEach(date => {
  content += `## 📅 ${date}\n\n`;
  grouped[date].forEach((article, idx) => {
    content += `### ${idx + 1}. ${article.title}\n\n`;
    content += `- 📝 **摘要**: ${article.digest || '暂无摘要'}\n`;
    content += `- ⏰ **发布时间**: ${article.post_time_str}\n`;
    content += `- 🔗 **原文链接**: [点击阅读](${article.url})\n`;
    content += `- 🖼️ **封面**: ${article.cover_url}\n`;
    content += `- ✅ **原创**: ${article.original === 1 ? '是' : '否'}\n`;
    content += `- 📍 **位置**: 第${article.position}条\n\n`;
  });
  content += `---\n\n`;
});

// 生成文档标题
const today = new Date().toISOString().split('T')[0];
const docTitle = `饼干哥哥AGI-文章汇总-第${data.dayInfo.currentDay}天-${today}`;

return [{
  json: {
    ...data,
    docTitle,
    docContent: content,
    articleCount: articles.length
  }
}];

const data = $input.first().json;
const createResponse = $input.all()[1]?.json || {};

const docToken = createResponse.data?.token || createResponse.token;

if (!docToken) {
  console.error('创建文档响应:', JSON.stringify(createResponse, null, 2));
  throw new Error('无法获取文档token');
}

console.log(`✅ 文档创建成功: ${docToken}`);

return [{
  json: {
    ...data,
    docToken,
    docUrl: `https://www.feishu.cn/docx/${docToken}`
  }
}];

