const data = $input.first().json;

// 保存进度到文件
const progress = {
  lastPage: data.endPage,
  totalArticles: data.articleCount,
  totalCost: data.totalCost,
  lastRun: new Date().toISOString(),
  day: data.dayInfo.currentDay,
  docUrl: data.docUrl
};

return [{
  json: {
    ...data,
    progress,
    status: 'success',
    message: `✅ 第 ${data.dayInfo.currentDay} 天完成！\n📄 文档: ${data.docTitle}\n🔗 链接: ${data.docUrl}\n📊 文章: ${data.articleCount} 篇\n💰 费用: ${data.totalCost.toFixed(2)} 元`
  }
}];
